correctedCode:
interface Payable {
    double calculatePay();
}

class Freelancer implements Payable {
    double rate;
    Freelancer(double rate) { this.rate = rate; }

    public double calculatePay() {
        return rate;
    }
}

public class Main {
    public static void main(String[] args) {
        Freelancer f = new Freelancer(500);
        System.out.println(f.calculatePay());
    }
}
